class AllOne {
    struct Node {
        int count;
        unordered_set<string> keys;
        Node* prev;
        Node* next;
        Node(int c) : count(c), prev(nullptr), next(nullptr) {}
    };

    Node* head;
    Node* tail;
    unordered_map<string, Node*> mp;

    void insertAfter(Node* node, Node* newNode) {
        newNode->prev = node;
        newNode->next = node->next;
        node->next->prev = newNode;
        node->next = newNode;
    }

    void removeNode(Node* node) {
        node->prev->next = node->next;
        node->next->prev = node->prev;
        delete node;
    }

public:
    AllOne() {
        head = new Node(0);
        tail = new Node(0);
        head->next = tail;
        tail->prev = head;
    }

    void inc(string key) {
        if (mp.find(key) == mp.end()) {
            Node* first = head->next;
            if (first != tail && first->count == 1) {
                first->keys.insert(key);
                mp[key] = first;
            } else {
                Node* newNode = new Node(1);
                newNode->keys.insert(key);
                insertAfter(head, newNode);
                mp[key] = newNode;
            }
        } else {
            Node* cur = mp[key];
            int newCount = cur->count + 1;
            Node* nxt = cur->next;
            cur->keys.erase(key);
            if (nxt != tail && nxt->count == newCount) {
                nxt->keys.insert(key);
                mp[key] = nxt;
            } else {
                Node* newNode = new Node(newCount);
                newNode->keys.insert(key);
                insertAfter(cur, newNode);
                mp[key] = newNode;
            }
            if (cur->keys.empty()) {
                removeNode(cur);
            }
        }
    }

    void dec(string key) {
        Node* cur = mp[key];
        int newCount = cur->count - 1;
        cur->keys.erase(key);
        if (newCount == 0) {
            mp.erase(key);
        } else {
            Node* prev = cur->prev;
            if (prev != head && prev->count == newCount) {
                prev->keys.insert(key);
                mp[key] = prev;
            } else {
                Node* newNode = new Node(newCount);
                newNode->keys.insert(key);
                insertAfter(cur->prev, newNode);
                mp[key] = newNode;
            }
        }
        if (cur->keys.empty()) {
            removeNode(cur);
        }
    }

    string getMaxKey() {
        if (tail->prev == head) return "";
        return *tail->prev->keys.begin();
    }

    string getMinKey() {
        if (head->next == tail) return "";
        return *head->next->keys.begin();
    }
};
